            if v != 9:
                edge_counts[v] = edge_counts.get(v, 0) + 1
    for r in range(h):
        for c in (0, w - 1):
            v = grid[r][c]
            if v != 9:
                edge_counts[v] = edge_counts.get(v, 0) + 1
    border = max(edge_counts, key=edge_counts.get)

    # The interior object color is the color of the scattered marks.
    counts = {}
    for row in grid:
        for v in row:
            if v != 9 and v != border:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return out
    ray_color = max(counts, key=counts.get)

    def cast(r, c, dr, dc):
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] == ray_color:
                out[r][c] = 4
                break
            if grid[r][c] != 9:
                break
            out[r][c] = ray_color
            r += dr
            c += dc

    for c in range(w):
        if grid[0][c] == border:
            cast(0, c, 1, 0)
        if grid[h - 1][c] == border:
            cast(h - 1, c, -1, 0)
    for r in range(h):
        if grid[r][0] == border:
            cast(r, 0, 0, 1)
        if grid[r][w - 1] == border:
            cast(r, w - 1, 0, -1)

    return out
